#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <map>
using namespace std;

void bitAdd(vector<long long>& t, long long i, long long x) {
    long long n = (long long)t.size() - 1;
    for (; i <= n; i += i & -i) t[i] += x;
}

long long bitSum(const vector<long long>& t, long long i) {
    long long s = 0;
    for (; i > 0; i -= i & -i) s += t[i];
    return s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long q;
    cin >> n >> q;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    vector<vector<long long>> qs(q, vector<long long>(2));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> qs[i][j];
        }
    }

    vector<int> order(q);
    for (int i = 0; i < q; i++) order[i] = i;
    sort(order.begin(), order.end(), [&](int x, int y) { return qs[x][1] < qs[y][1]; });
    map<long long, long long> last;
    vector<long long> t(n + 1, 0), ans(q);
    long long p = 0;
    for (int idx : order) {
        long long l = qs[idx][0], rr = qs[idx][1];
        while (p < rr) {
            p++;
            long long v = a[p - 1];
            auto it = last.find(v);
            if (it != last.end()) bitAdd(t, it->second, -1);
            last[v] = p;
            bitAdd(t, p, 1);
        }
        ans[idx] = bitSum(t, rr) - bitSum(t, l - 1);
    }
    for (int i = 0; i < q; i++) cout << (i ? " " : "") << ans[i];
    cout << "\n";

    return 0;
}

