import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static void bitAdd(long[] t, int i, long x) {
        int n = t.length - 1;
        for (; i <= n; i += i & -i) t[i] += x;
    }

    static long bitSum(long[] t, int i) {
        long s = 0;
        for (; i > 0; i -= i & -i) s += t[i];
        return s;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[][] qs = new long[(int) q][2];
        for (int i = 0; i < qs.length; i++) {
            for (int j = 0; j < qs[i].length; j++) {
                qs[i][j] = Long.parseLong(next());
            }
        }

        int cn = (int) n, cq = (int) q;
        long[] keys = new long[cq];
        for (int i = 0; i < cq; i++) keys[i] = (qs[i][1] << 15) | i;
        Arrays.sort(keys);
        long[] sortedVals = a.clone();
        Arrays.sort(sortedVals);
        int m = 0;
        for (int i = 0; i < cn; i++) {
            if (i == 0 || sortedVals[i] != sortedVals[i - 1]) sortedVals[m++] = sortedVals[i];
        }
        int[] last = new int[m];
        long[] t = new long[cn + 1];
        long[] ans = new long[cq];
        int p = 0;
        for (int k = 0; k < cq; k++) {
            int idx = (int) (keys[k] & 32767L);
            int l = (int) qs[idx][0], rr = (int) qs[idx][1];
            while (p < rr) {
                p++;
                int id = Arrays.binarySearch(sortedVals, 0, m, a[p - 1]);
                if (last[id] != 0) bitAdd(t, last[id], -1);
                last[id] = p;
                bitAdd(t, p, 1);
            }
            ans[idx] = bitSum(t, rr) - bitSum(t, l - 1);
        }
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < cq; i++) {
            if (i > 0) out.append(" ");
            out.append(ans[i]);
        }
        System.out.println(out);
    }
}
